-- No row is superseded; Sam said nothing in session, so every row is proposed.
insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-reconcile-hold-other-page-only-s658','decision','A reconcile skips a held record only when the hold names another page','S658, #3363: reconcile_filed reads the filed capture''s held_worse_window and held_no_gain and skips a record only when the hold''s url differs from the record''s source_url (07206''s mid-table window). A hold on the record''s own page (Santiago Canyon 135 of 136 held_no_gain) guards a paid read only, so the reconcile reads it. Hold lists are merged back and programs recounted.',array['program-requirements','reconcile','decision'],'proposed','S658 checkpoint; docs/session_658_handoff.md, #3352 and #3363',null,null,'SkyDunlin (S658)',date '2026-11-15'),
('p-display-diff-against-live-before-s658','pitfall','Diff a display apply against each row''s live before build, never the last build file','S657 and S658, #3352: build 58b763170559 was diffed against a83667f9fa0d, but the applied record''s before map names 7 live builds (bef8ef819af7 16,984 rows; a83667f9fa0d 59). Diffing each row against its own before build, from the committed .sql.gz, found the 315 out-of-wave rows and their causes. Read the thread again just before a whole-build dispatch.',array['program-requirements','display','pitfall'],'proposed','S658 checkpoint; docs/session_658_handoff.md, #3352 and #3363',null,null,'SkyDunlin (S658)',date '2026-11-15'),
('rescore-out-of-wave-rows-traced-s658','fact','The course-id wave''s 315 out-of-wave display rows, traced','S658, #3352 merged 20b02884: of 451 display rows that moved, 315 sat outside the six colleges: 93 FIRE 130 X''s wider peer lists (#3245 case 2, #3298), 188 an Honors base title dropped or the HUMA M10ME and BUSI M10XW splits (#3329, #3245 case 6), 34 the S654 wave''s checks and gaps (#3345). No row fell in coverage or status; COBIx closed its point.',array['program-requirements','display','fact'],'proposed','S658 checkpoint; docs/session_658_handoff.md, #3352 and #3363',null,null,'SkyDunlin (S658)',date '2026-11-15')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyDunlin (S658)', 'create', 'S658 checkpoint (2026-11-15)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('d-reconcile-hold-other-page-only-s658','p-display-diff-against-live-before-s658','rescore-out-of-wave-rows-traced-s658')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in ('d-reconcile-hold-other-page-only-s658','p-display-diff-against-live-before-s658','rescore-out-of-wave-rows-traced-s658') group by m.slug, m.summary order by m.slug;
